\label{def:4PI}
		Given a matrix $P$ and polynomials $Q_1,Q_2,R_0$, $R_1$, $R_2$, we say that $\mathcal{P}$ is a \textbf{4-PI operator} if               
			\begin{align*}\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}
				&\left(\mathcal{P} \begin{bmatrix} x\\\mathbf{x} \end{bmatrix} \right)(s) := \begin{bmatrix} Px + \int_{a}^{b}Q_1(\theta)\mathbf{x}(\theta)d\theta\\Q_2(s)x+ \left(\mathcal{R}\mathbf{x}\right) (s) \end{bmatrix}, \text{where}~\left(\mathcal{R}\mathbf{x}\right)(s)\\
	&\hspace{-0.5mm}=\hspace{-0.5mm}R_0(s) \mathbf{x}(s) +\hspace{-1.5mm}\int_{a}^s  \hspace{-1.5mm}R_1(s,\theta)\mathbf{x}(\theta)d \theta+\hspace{-1.5mm}\int_s^b \hspace{-1.5mm}R_2(s,\theta)\mathbf{x}(\theta)d \theta.		
			\end{align*}               

            We denote the map from $P,Q_i,R_i \mapsto \mathcal{P}$ as \[\mathcal{P}= \hspace{0.5mm}\scalebox{0.9}[1.2]{$\mathit{\Pi}$}\hspace{-1.mm}\left[\begin{array}{c|c}
P&Q_1\\\hline Q_2 & \left\{R_i\right\}
\end{array}\right]\subset \mathcal{L}(\mathbb{R}^m \times L_2^{n},\mathbb{R}^p \times L_2^{q})\] and, $\mathcal{P} \in \pmb{\Pi}$ if $\mathcal{P}$ is a 4-PI operator.

\label{def:system}
 Given $\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},\mathcal{H} \in \pmb{\Pi}$ and $v$, $w$, we say $z=G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},\mathcal{H})(w,v)$ if there exists $x(t)$ such that                
 \begin{align}
\!\partial_t( \mathcal T x(t)) \!= \!\mathcal A x(t)\!+\!\mathcal{B}w(t),
   \mathcal T x(0) \!=\! \mathcal{H} v,           
z(t) = \mathcal Cx(t),
    \label{eq:PIE}
\end{align}

\label{def:2,i_norm}
Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$ with $G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})$ well-posed, define
    \begin{equation}
\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}:=   \sup_{T\ge 0} \sup_{\substack{z,\mathbf{x}\, \text{satisfy~\eqref{eq:primal_aux}}\\ \left\lVert{v}\right\rVert_2=1}} \left\lVert{z}\right\rVert_{L_2[0,T]}.           
    \label{eq:primal_proxy_norm}
\end{equation}

\label{def:inf,2_norm}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$ with $G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)$ well-posed, define
    \begin{equation}
\|G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)\|_{\infty,2}=\sup_{T >0}
   \sup_{\substack{v,x\, \text{satisfy~\eqref{eq:dualPIE}}\\\left\lVert{v}\right\rVert_{L_2[0,T]}=1} } \|z (T)\|.              
    \label{eq:dual_norm}
\end{equation}

\label{prop:H2equi_PIE}
Given $\mathcal{T,A,B, C}\in\pmb{\Pi}$, where the domain of $\mathcal{B}$ is $\mathbb{R}^{n_w}$, and the image of $\mathcal{C}$ is $\mathbb{R}^{n_z}$, suppose $\hat G(s)=\mathcal{C}(s\mathcal{T}-~\mathcal{A})^{-1}\mathcal{B}$ exists.                                   






Then we have the following.


    \[ \hspace{-2mm}
\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i} \le\hspace{-1mm} \|\hat G\|_{H_2}\hspace{-1mm}\le \sqrt{n_w} \|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}
\]

  \[\hspace{-3mm}
\|G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)\|_{\infty,2} \le\hspace{-1mm} \|\hat G\|_{H_2}\hspace{-1mm}\le \sqrt{n_z} \|G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)\|_{\infty,2}
\]

\label{lem:intertwining}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose $x,v$ satisfy Eqn.~\eqref{eq:primal_aux} for $\{\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C}\}$, and $\bar x,\bar v$ satisfy Eqn.~\eqref{eq:dualPIE} for $\{\mathcal{T}^*, \mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*\}$. Then, for any $T>0$, we have the following
\begin{align}
    \label{eq:intertwining2}
 \bigl(\mathcal{B}^* \bar x(T) \bigr)^T v=  \int_0^T\left\langle \bar v(T-t),\mathcal{C} x(t)\right\rangle dt.
\end{align}

Recall that   
\[
\|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}=    \sup_{T>0}
   \sup_{\substack{v,x\, \text{satisfy~\eqref{eq:dualPIE}}\\\left\lVert{v}\right\rVert_{L_2[0,T]}=1} } \|\mathcal{B}^* x(T)\|,              
\]
\[
\text{and }\;\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}:= \sup_{T>0}   \sup_{\substack{v,z,\mathbf{x}\text{satisfy~\eqref{eq:primal_aux}}\\ \left\lVert{v}\right\rVert_2=1}} \left\lVert{z}\right\rVert_{L_2[0,T)}.                                                                                                   
\]







To show that $\|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}\le \|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}$, we establish that for any $T>0$ and any $\bar{v}$, $\bar{x}$ which satisfy satisfy Eq. (5) with $\left\lVert{\bar{v}}\right\rVert_{L_2[0,T]}=1$, we have that $|\mathcal{B}^* x(T)|\le \|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}$.

Specifically, for $T>0$ and any $\bar{v}$, $\bar{x}$ which satisfy Eq. (5) with $\left\lVert{\bar{v}}\right\rVert_{L_2[0,T]}=1$, let $v = \frac{1}{\left\lVert{\mathcal{B}^*\bar{x}(T)}\right\rVert}\mathcal{B}^*\bar{x}(T)$ and $x,z$ satisfy Eq. (2) for this $v$. Then from Lem.~\ref{lem:intertwining},
\begin{align*}
    \left\lVert{\mathcal{B}^*\bar{x}(T)}\right\rVert &= (\mathcal{B}^*\bar{x}(T))^Tv= \int_0^T\left\langle v(T-t),\mathcal{C}x(t)\right\rangle dt\\
    &\hspace{-1.5cm}\le\! \left\lVert{v}\right\rVert_{L_2[0,T]}\!\left\lVert{z}\right\rVert_{L_2[0,T]}\! =\!\left\lVert{z}\right\rVert_{L_2[0,T]}\!\le\! \|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}
\end{align*}
as desired, where the final inequality holds from the definition of $\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}$ and the fact that $v,x,z$ satisfy Eq. (2) with $\left\lVert{v}\right\rVert=1$. Since the bound holds uniformly for any $T>0$ and any $\bar{v}$, $\bar{x}$ which satisfy Eq. (5) with $\left\lVert{\bar{v}}\right\rVert_{L_2[0,T]}=1$, we conclude that
\begin{align*}
\|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}&=    \sup_{T>0}
   \sup_{\substack{v,x\, \text{satisfy~\eqref{eq:dualPIE}}\\\left\lVert{v}\right\rVert_{L_2[0,T]}=1} } |\mathcal{B}^* x(T)|\\
   &\le \|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}.
\end{align*}



Now, to show that $\|G(\mathcal{T},\mathcal{A},0, \mathcal{C},\mathcal{B})\|_{2,i}\le \|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}$, we similarly establish that for any $T>0$ and any $v$, $z$ $x$ which satisfy Eq.~\eqref{eq:primal_aux} with $\left\lVert{v}\right\rVert=1$, we have that $\left\lVert{z}\right\rVert_{L_2[0,T)} \le \|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}$.

Specifically, for $T>0$ and any $v$, $z$ $x$ which satisfy Eq.~\eqref{eq:primal_aux} with $\left\lVert{v}\right\rVert=1$, let $\bar v(t) = \frac{1}{\left\lVert{z}\right\rVert_{L_2[0,T)}}z(T-t)$ and $\bar x$ satisfy Eq.~\eqref{eq:dualPIE} for this $\bar v$. Then from Lem.~\ref{lem:intertwining},
\begin{align*}
\left\lVert{z}\right\rVert_{L_2[0,T]}&=\frac{1}{\left\lVert{z}\right\rVert_{L_2[0,T)}}\int_0^T \left\langle z(t),z(t)\right\rangle dt\\
&\hspace{-1.4cm}=\int_0^T \left\langle \bar v(T-t),\mathcal{C} x (t)\right\rangle dt=\bigl(\mathcal{B}^* \bar x(T) \bigr)^T v\\
&\hspace{-1.4cm}\le \left\lVert{\mathcal{B}^* \bar x(T) }\right\rVert\!\left\lVert{ v}\right\rVert\!=\!\left\lVert{\mathcal{B}^* \bar x(T) }\right\rVert\!\le\! \|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}
\end{align*}
where the final inequality holds from the definition of $\|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}$ and the fact that $\bar v,\bar x$ satisfy Eq.~\eqref{eq:dualPIE} with $\left\lVert{\bar v}\right\rVert=1$. Since the bound holds uniformly for any $T>0$ and any  $v$, $z$ $x$ which satisfy Eq.~\eqref{eq:primal_aux} with $\left\lVert{v}\right\rVert=1$, we conclude that
\begin{align*}
\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}&=    \sup_{T>0}   \sup_{\substack{v,z,\mathbf{x}\text{satisfy~\eqref{eq:primal_aux}}\\ \left\lVert{v}\right\rVert_2=1}} \left\lVert{z}\right\rVert_{L_2[0,T)}\\
&\le \|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}
\end{align*}
as desired. 
We conclude that $\|G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})\|_{2,i}=\|G(\mathcal{T}^*,\mathcal{A}^*,\mathcal{C}^*,\mathcal{B}^*,0)\|_{\infty,2}$.

\label{thm:LPI_2,i}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose there exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma, \epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying \begin{align}
\mathcal A^*\mathcal P\mathcal T
+\mathcal T^*\mathcal P\mathcal A
+            
\mathcal C^*\mathcal C
&\preccurlyeq 0,\;



\mathcal B^*\mathcal P\mathcal B         

\preccurlyeq \gamma I.
\label{eq:lpi1b}
\end{align}
Then, $\left\lVert{G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})}\right\rVert_{2,i}^2 \leq \gamma$.

\label{thm:LPI_inf,2}
 Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose there exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma, \epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying
\begin{align}
         \begin{bmatrix} -\gamma I & \mathcal{B^*PT}\\ \mathcal{T^* P B} & \mathcal{A^*PT+T^*PA} \end{bmatrix} &\preccurlyeq0, \;                                  

        \mathcal{C^*C}-\mathcal{T^*PT}  
        \preccurlyeq0.\label{eq:lpi1d}
     \end{align}
Then, $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}^2 \leq \gamma$

We prove that if there exist $\mathcal{P} \succcurlyeq \epsilon I, \gamma >0$ satisfying                           
 Eqn.~\eqref{eq:lpi1d}, then $\|G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)\|_{\infty,2}^2 \leq \gamma$, recalling that
\[\|G(\mathcal{T},\mathcal{A},\mathcal{B},\mathcal{C},0)\|_{\infty,2}=    \sup_{T >0}
   \sup_{\substack{v,x\, \text{satisfy~\eqref{eq:dualPIE}}\\\left\lVert{v}\right\rVert_{L_2[0,T]}=1} } \|z (T)\|.\]

     Suppose there exist $\mathcal{P}\succcurlyeq \epsilon I, \gamma>0$ satisfying                            
     Eqn.~\eqref{eq:lpi1d}. For any $T>0$, suppose $z,x, v$ satisfy Eqn.~\eqref{eq:dualPIE}, given some input with $\left\lVert{v}\right\rVert_{L_2[0,T]} = 1$. 
     Define the storage functional \(V(x(t))=\left\langle x(t), \mathcal{T^* PT} x(t)\right\rangle.\) Then, $V(x)\ge \epsilon \left\lVert{\mathcal{T}\bar{x}}\right\rVert^2$ and 
   {\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}
    \begin{align*}
        \dot V(x(t))=\left\langle x(t),(\mathcal{A^* PT+T^*PA}) x(t)\right\rangle+2\left\langle v,\mathcal{B^*PT} x(t)\right\rangle,                          
    \end{align*}}
implying that, since $\mathcal{P}$ and $\gamma$ satisfy Eqn.~\eqref{eq:lpi1d},
    \begin{align*}
            \dot V(x(t))&-\gamma \left\lVert{v(t)}\right\rVert_2^2=\\
            &\hspace{-4mm}\left\langle \begin{bmatrix} v(t)\\ x(t) \end{bmatrix}, \begin{bmatrix} -\gamma I & \mathcal{B^*PT}\\\mathcal{T^*PB}& \mathcal{A^*PT+T^*PA} \end{bmatrix}\begin{bmatrix} v(t)\\ x(t) \end{bmatrix}\right\rangle \leq 0.
    \end{align*}
Integrating $\dot{V}$ w.r.t. $t$ over $[0,T]$, we get
\begin{align*}
V(x(T))-V(x(0))-\gamma \left\lVert{v}\right\rVert_{L_2[0,T]}^2 \leq 0.
\end{align*}




Then, since $\mathcal{P}$ and $\gamma$ satisfy Eqn.~\eqref{eq:lpi1d}, we have that
\begin{align*}
          \left\lVert{z(T)}\right\rVert_2^2                          
          &=
          \left\langle x(T), \mathcal{C^*C}x(T)\right\rangle\leq\left\langle x(T),\mathcal{T^*PT} x(T)\right\rangle\\&= V(x(T))
          =V(x(T)-V(x(0))\leq\gamma\left\lVert{v}\right\rVert^2=\gamma              

    \end{align*}

    Since the inequality holds uniformly for any $T>0$ and solutions of Eqn. \eqref{eq:dualPIE},                                                                           
by the definition of the energy-to-peak norm, we conclude that $
\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}^2 \leq \gamma$, as desired.

\label{lem:schur} Given Hilbert spaces $X$ and $Y$, $\mathcal{R}\in\mathcal{L}(X)$, $\mathcal{S}\in\mathcal{L}(Y)$, and $\mathcal{U}\in\mathcal{L}( Y, X)$ with $\mathcal{S} \succcurlyeq \epsilon I$ for some $\epsilon>0$. Then the following are equivalent.
\begin{enumerate} 
\item 
$\displaystyle \begin{bmatrix} \mathcal{S}&\mathcal{U}\\\mathcal{U}^*&\mathcal{R} \end{bmatrix}\succcurlyeq 0 $.
\item $\displaystyle \mathcal{R}-\mathcal{U}^* \mathcal{S}^{-1} \mathcal{U} \succcurlyeq 0$.
\end{enumerate}

\label{cor:LPI_2,i_dual}
 Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose there exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma, \epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying
\begin{align}
         \begin{bmatrix} -\gamma I & \mathcal{CPT^*}\\ \mathcal{T P C^*} & \mathcal{APT^*+TPA^*} \end{bmatrix} &\preccurlyeq0,\;                                   

        \mathcal{BB^*}-\mathcal{TPT^*}              

        \preccurlyeq0.\label{eq:lpi6b_}
     \end{align}

Then, $\left\lVert{G(\mathcal{T,A},0,\mathcal{C},\mathcal{B})}\right\rVert_{2,i}^2 \leq \gamma$

\label{thm:LPIs_2,i_dilated}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose at least one of the following            
    statements hold.
    \begin{enumerate}
        \item There exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma, \epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$,  satisfying, \begin{align}
\begin{bmatrix} -\gamma I & \mathcal{C} \\\mathcal{C}^* &\mathcal A^*\mathcal P\mathcal T
+\mathcal T^*\mathcal P\mathcal A \end{bmatrix}
&\preccurlyeq 0, \,             

\begin{bmatrix} \mathcal{P} &\mathcal{PB}\\ \mathcal{B^*P} &\gamma I  \end{bmatrix} &\succcurlyeq 0            
\label{eq:lpi2b}




\end{align}
\item  There exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma,\epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I $, satisfying
\begin{align}
         \begin{bmatrix} -\gamma I & \mathcal{CPT^*}\\ \mathcal{T P C^*} & \mathcal{APT^*+TPA^*} \end{bmatrix} &\preccurlyeq0, \,                                  
         \begin{bmatrix} \gamma I & \mathcal{B}^*\\\mathcal{B} &  \mathcal{TPT^*} \end{bmatrix}  
         \succcurlyeq 0\label{eq:lpi3b}.
     \end{align}
    \end{enumerate}

Then,                                             
$\left\lVert{G(\mathcal{T},\mathcal{A},0,\mathcal{C},\mathcal{B})}\right\rVert_{2,i}
\leq \gamma$.

\label{cor:LPI_inf,2_dual}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose there exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma,\epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying\begin{align}
\mathcal A\mathcal P\mathcal T^*
+\mathcal T\mathcal P\mathcal A^*
+            
\mathcal B\mathcal B^*
&\preccurlyeq 0, \;\;              


\mathcal{CPC^*} 

\preccurlyeq \gamma I.
\label{eq:lpi4b}
\end{align}
Then, $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}^2 \leq \gamma$.

We prove that if                           
Eqn.~\eqref{eq:lpi4b} hold for some $\mathcal{P}\succcurlyeq \epsilon I, \gamma>0$, then $\left\lVert{G(\mathcal{T^*,A^*},0,\mathcal{B}^*,\mathcal{C}^*)}\right\rVert_{2,i}^2 \leq \gamma$. We use duality, in Thm.~\ref{thm:dualnorm}, to assert that $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}^2 \leq \gamma$. 
Suppose there exist $\mathcal{P}\succcurlyeq \epsilon I, \gamma>0$ satisfying                             
Eqn.~\eqref{eq:lpi4b}.
Let $\mathcal{T'=T^*}$, $\mathcal{A'=A^*}$, $\mathcal{B'=C^*}$, and $\mathcal{C'=B^*}$. By Thm.~11.3 of Chapter II of~\cite{gohbergVol1}, $(A^*)^*=A$ for any $A\in \mathcal{L}(X)$. Since $\mathcal{T,A,B,C} \in \pmb{\Pi} \subset \mathcal{L}(X)$, we have $(\mathcal{T}')^*=\mathcal{T}$, $(\mathcal{A}')^*=\mathcal{A}$, $(\mathcal{C}')^*=\mathcal{B}$, and $(\mathcal{B}')^*=\mathcal{C}$ and consequently, conditions of  Thm.~\ref{thm:LPI_2,i} hold,
\begin{align*}
    (\mathcal A')^*\mathcal P\mathcal T'
+(\mathcal T')^*\mathcal P\mathcal A'
+(\mathcal C')^*\mathcal C'
\preccurlyeq 0,\;
\mathcal{(B')^*PB'} 
\preccurlyeq \gamma I,
\end{align*}
and hence we conclude that \(\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}^2\leq \gamma.\) 
Lastly, from Thm.~\ref{thm:dualnorm}, we have that
\begin{align*}
    \gamma&\ge \left\lVert{G(\mathcal{T}'\!,\!\mathcal{A}'\!,0,\!\mathcal{C}'\!,\!\mathcal{B}')}\right\rVert_{2,i}^2\\
    &=\left\lVert{G((\mathcal{T}')^*\!,\!(\mathcal{A}')^*\!,\!(\mathcal{C}')^*\!,\!(\mathcal{B}')^*\!,\!0)}\right\rVert_{\infty,2}^2\\&=\left\lVert{G(\mathcal{(T^*)^*,(A^*)^*,(B^*)^*,(C^*)^*},0)}\right\rVert_{\infty,2}^2\\
    &=\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}^2.
\end{align*}

\label{thm:LPIs_inf,2_dilated}
    Given $\mathcal{T,A,B,C} \in \pmb{\Pi}$, suppose at least one of the following statements hold.
    \begin{enumerate}










        \item There exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma,\epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying
\begin{equation}\label{eq:lpi5b}
\hspace{-6mm}\begin{bmatrix} -\gamma I & \mathcal{B}^* \\\mathcal{B}&\mathcal A\mathcal P\mathcal T^*
+\mathcal T\mathcal P\mathcal A^* \end{bmatrix}\preccurlyeq 0             
\quad 
\begin{bmatrix} \mathcal{P}  &\mathcal{PC^*}\\ \mathcal{CP}&\gamma I  \end{bmatrix} \succcurlyeq 0
\end{equation}
\item  There exist $\mathcal{P}=\mathcal{P}^* \in \pmb{\Pi}$, and $\gamma,\epsilon>0$, such that $\mathcal{P} \succcurlyeq \epsilon I$, satisfying
\begin{equation}\label{eq:lpi6b}
\hspace{-6mm}\begin{bmatrix} -\gamma I & \mathcal{B^*PT}\\ \mathcal{T P B} & \mathcal{A^*PT+T^*PA} \end{bmatrix} \preccurlyeq0             
\quad 
\begin{bmatrix} \gamma I & \mathcal{C}\\\mathcal{C}^* & \mathcal{T^*PT} \end{bmatrix}\succcurlyeq 0
\end{equation}

    \end{enumerate}

Then, $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2} \leq \gamma$.

We use the duality result of Thm.~\ref{thm:dualnorm}, to prove that the LPIs in statements $1)$ and $2)$ imply $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2} \leq \gamma$. First, we show $1)$ implies $\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i} \leq \gamma$.

Suppose $1)$ holds for some $\mathcal{P}\succcurlyeq \epsilon I,\gamma>0$. Then, $\mathcal{P}, \gamma$ satisfy Eqn.~\eqref{eq:lpi5b}.

Now, let $\mathcal{T'=T^*}$, $\mathcal{A'=A^*}$, $\mathcal{B'=C^*}$, and $\mathcal{C'=B^*}$. Then, statement $1)$ of Thm.~\ref{thm:LPIs_2,i_dilated} hold for $G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')$:
\begin{align*}
\begin{bmatrix} -\gamma I & \mathcal{C}' \\(\mathcal{C}')^* &(\mathcal A')^*\mathcal P\mathcal T'
+(\mathcal T')^*\mathcal P\mathcal A' \end{bmatrix}
\!\preccurlyeq\! 0, \;\begin{bmatrix} \gamma I&(\mathcal{B}')^*\mathcal{P}\\ \mathcal{P} \mathcal{B}'&\mathcal{P} \end{bmatrix} \!\succcurlyeq\! 0,            
\end{align*}
which implies that \(\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}\leq \gamma.\)  





















Next, we show that $2)$ implies $\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i} \leq \gamma$. 
Suppose $2)$ holds for some $\mathcal{P}\succcurlyeq \epsilon I,\gamma>0$. Then, $\mathcal{P}, \gamma$ satisfy Eqn.~\eqref{eq:lpi6b}. Hence, statement $2)$ of Thm.~\ref{thm:LPIs_2,i_dilated} hold for $G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')$. Specifically, we have that
{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}
\begin{align*}
       \begin{bmatrix} -\gamma I &\hspace{-2 mm} \mathcal{C'P(T')^*}\\ \mathcal{T' P (C')^*} &\hspace{-2 mm} \mathcal{A'P(T')^*+T'P(A')^*} \end{bmatrix} \preccurlyeq0,
         \begin{bmatrix} \gamma I &\hspace{-1 mm} (\mathcal{B}')^*\\\mathcal{B}' &\hspace{-1 mm} \mathcal{T'P(T')^*} \end{bmatrix}\succcurlyeq 0,                  
\end{align*}}
which implies that \(\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}\leq \gamma.\)  

Now, we are in position to invoke Thm.~\ref{thm:dualnorm}, using $G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')$, which states that
\begin{align*}
    \left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}&=\left\lVert{G(\mathcal{T}^*,\mathcal{A}^*,0,\mathcal{B}^*,\mathcal{C}^*)}\right\rVert_{2,i}\\&\hspace{-9mm}=\left\lVert{G(\mathcal{(T')^*,(A')^*,(B')^*,(C')^*},0)}\right\rVert_{\infty,2}. 
\end{align*}

Since $\mathcal{T,A,B,C} \in \pmb{\Pi} \subset \mathcal{L}(X)$, we have that, by Thm.~11.3 of Chapter II of~\cite{gohbergVol1}, $(\mathcal{T}')^*=\mathcal{T}^{**}=\mathcal{T}$, $(\mathcal{A}')^*=\mathcal{A}^{**}=\mathcal{A}$, $(\mathcal{B}')^*=\mathcal{B}^{**}=\mathcal{B}$, and $(\mathcal{C}')^*=\mathcal{C}^{**}=\mathcal{C}$, and hence 
\[
\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}=\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}.
\]

Since both $1)$ and $2)$ imply $\left\lVert{G(\mathcal{T}',\mathcal{A}',0,\mathcal{C}',\mathcal{B}')}\right\rVert_{2,i}\leq \gamma$, both imply $\left\lVert{G(\mathcal{T,A,B,C},0)}\right\rVert_{\infty,2}\leq \gamma$, as desired.
